users.code:
// Block /?author=N redirects
add_action('template_redirect', function(){
    if (!empty($_GET['author']) && is_numeric($_GET['author'])) {
        wp_redirect(home_url(), 301); exit;
    }
});
// Strip users endpoint from REST
add_filter('rest_endpoints', function($endpoints){
    unset($endpoints['/wp/v2/users']);
    unset($endpoints['/wp/v2/users/(?P<id>[\d]+)']);
    return $endpoints;
});

tls_headers.code:
add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;
add_header X-Content-Type-Options nosniff always;
add_header X-Frame-Options SAMEORIGIN always;
add_header Referrer-Policy strict-origin-when-cross-origin always;
add_header Permissions-Policy "camera=(), microphone=(), geolocation=()" always;
add_header Content-Security-Policy "default-src 'self' https:; object-src 'none'; frame-ancestors 'self'; base-uri 'self'" always;
server_tokens off;

